// Payroll & Paycheck Calculator — SEO content
// ---------------------------------------------------------------------------
// Worked examples are generated by calculatePaycheck(), the same engine the
// calculator runs, so the numbers in the article always match the tool.

import {
  calculatePaycheck,
  FEDERAL_STANDARD_DEDUCTION,
  PERIODS_PER_YEAR,
  SOCIAL_SECURITY_WAGE_BASE,
  TAX_YEAR,
  type FilingStatus,
  type PaycheckInput,
  type PayFrequency,
} from '@/lib/payroll/withholding-2026';
import { STATE_CODES, STATE_PAYCHECK_PAGES } from '@/lib/payroll/state-pages';

const usd = (n: number) => n.toLocaleString('en-US', { style: 'currency', currency: 'USD' });
const pct = (n: number) => `${(n * 100).toFixed(1)}%`;

const FREQ_WORD: Record<PayFrequency, string> = {
  weekly: 'weekly',
  'bi-weekly': 'every two weeks',
  'semi-monthly': 'twice a month',
  monthly: 'monthly',
};

const STATUS_WORD: Record<FilingStatus, string> = {
  single: 'single',
  married: 'married filing jointly',
  hoh: 'head of household',
};

interface Scenario {
  title: string;
  salary: number;
  where: string;
  deductionsNote?: string;
  input: Omit<PaycheckInput, 'hourlyRate' | 'regularHoursPerWeek' | 'overtimeHoursPerWeek' | 'overtimeMultiplier'>;
}

// A salary is run through the engine as 40 hours a week at salary ÷ 2,080
function salaryInput(s: Scenario): PaycheckInput {
  return {
    ...s.input,
    hourlyRate: s.salary / 2080,
    regularHoursPerWeek: 40,
    overtimeHoursPerWeek: 0,
    overtimeMultiplier: 1.5,
  };
}

function describe(s: Scenario) {
  const r = calculatePaycheck(salaryInput(s));
  const lines = r.deductions.map((d) => `${d.label} ${usd(d.perPeriod)}`).join(', ');
  return {
    title: s.title,
    description:
      `A ${usd(s.salary)} salary paid ${FREQ_WORD[s.input.payFrequency]}, filing ${STATUS_WORD[s.input.filingStatus]}, ${s.where}${s.deductionsNote ? `, ${s.deductionsNote}` : ''}. ` +
      `Gross pay is ${usd(r.grossPerPeriod)} per paycheck. ` +
      `Taken out of each paycheck: ${lines}. ` +
      `Take-home pay: ${usd(r.netPerPeriod)} per paycheck, or ${usd(r.netAnnual)} a year (${usd(r.netAnnual / 12)} a month). ` +
      `Deductions take ${pct(r.effectiveRate)} of gross pay.`,
  };
}

